package com.saas.support.service;

import com.saas.support.dto.NoteUpdateDto;
import com.saas.support.entity.SupportTicket;
import com.saas.support.repository.SupportTicketRepository;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/support/tickets")
public class SupportTicketController {

    private final SupportTicketRepository ticketRepository;

    public SupportTicketController(SupportTicketRepository ticketRepository) {
        this.ticketRepository = ticketRepository;
    }

    @PatchMapping("/{ticketId}/notes")
    public ResponseEntity<String> addCustomerNote(
            @PathVariable Long ticketId,
            @RequestBody NoteUpdateDto noteDto,
            Authentication authentication) {
        SupportTicket ticket = ticketRepository.findById(ticketId)
                .orElseThrow(() -> new IllegalArgumentException("Ticket not found"));
        if (!ticket.getOwnerUsername().equals(authentication.getName()) && !ticket.getAssignedAgentUsername().equals(authentication.getName())) {
            throw new AccessDeniedException("User does not have permission to append notes to this ticket");
        }
        ticket.appendInternalNote(noteDto.getNoteContent());
        ticketRepository.save(ticket);
        return ResponseEntity.ok("Note appended to ticket");
    }
}
